import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

class AppImages {
  static const String studentAvatarBase64 = '';
  static final Uint8List studentAvatarBytes = base64Decode(studentAvatarBase64);

  static Widget studentAvatar({double? width, double? height, BoxFit fit = BoxFit.cover, BorderRadius? borderRadius}) {
    final img = Image.memory(
      studentAvatarBytes,
      width: width,
      height: height,
      fit: fit,
      errorBuilder: (context, error, stackTrace) => const Icon(Icons.child_care, size: 30),
    );
    if (borderRadius != null) {
      return ClipRRect(borderRadius: borderRadius, child: img);
    }
    return img;
  }

  static const String rohLogoBase64 = '';
  static final Uint8List rohLogoBytes = base64Decode(rohLogoBase64);

  static Widget rohLogo({double? width, double? height, BoxFit fit = BoxFit.contain}) {
    return Image.memory(
      rohLogoBytes,
      width: width,
      height: height,
      fit: fit,
      errorBuilder: (context, error, stackTrace) => const Text('ROH', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18)),
    );
  }

  static const String therapistAvatarBase64 = '';
  static final Uint8List therapistAvatarBytes = base64Decode(therapistAvatarBase64);

  static Widget therapistAvatar({double radius = 18}) {
    return CircleAvatar(
      radius: radius,
      backgroundImage: MemoryImage(therapistAvatarBytes),
      backgroundColor: Colors.transparent,
    );
  }

  static Widget therapistImage({double? width, double? height, BoxFit fit = BoxFit.cover, BorderRadius? borderRadius}) {
    final img = Image.memory(
      therapistAvatarBytes,
      width: width,
      height: height,
      fit: fit,
      errorBuilder: (context, error, stackTrace) => const Icon(Icons.person, size: 40),
    );
    if (borderRadius != null) {
      return ClipRRect(borderRadius: borderRadius, child: img);
    }
    return img;
  }
}
